Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
  try {
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
    );
    const { data: cats, error: ce } = await supabase
      .from("prompt_categories").select("id, slug");
    if (ce) throw ce;
    const slugMap = new Map<string, string>();
    cats!.forEach((c) => slugMap.set(c.slug, c.id));

    const rows = RECORDS.map((r) => ({
      category_id: slugMap.get(r.category_slug),
      title: r.title,
      prompt_text: r.prompt_text,
      follow_up: r.follow_up,
      purpose: r.purpose,
      outcome: r.outcome,
      output_format: r.output_format,
      time_saved: r.time_saved,
      relevance: r.relevance,
      utility: r.utility,
      revenue_potential: r.revenue_potential,
      tier: r.tier,
      sort_order: r.sort_order,
    })).filter(r => r.category_id);

    // Insert in chunks of 50
    let inserted = 0;
    for (let i = 0; i < rows.length; i += 50) {
      const chunk = rows.slice(i, i + 50);
      const { error } = await supabase.from("prompts").insert(chunk);
      if (error) throw error;
      inserted += chunk.length;
    }

    return new Response(JSON.stringify({ inserted, total: rows.length }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    return new Response(JSON.stringify({ error: String(e) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});
